export declare function dedupeQualityFlags(qualityFlags: readonly string[]): string[];
/** Stores `regex` under `key`, evicting the oldest entry once the cache is full. */
export declare function rememberCachedRegex(cache: Map<string, RegExp>, key: string, regex: RegExp): RegExp;
/** Non-finite or missing limits fall back; anything else is truncated and clamped to 1..max. */
export declare function clampLimit(limit: number | undefined, fallback: number, max: number): number;
export declare function hasPartialNetMinecraftCoverage(qualityFlags: string[]): boolean;
/** The line at `lineIndex` (0-based) joined with up to one line before and after it. */
export declare function extractLineContext(lines: string[], lineIndex: number): string;
